        let limits=XmlLimits{input_bytes:MAX_LARGE_INPUT_BYTES,..XmlLimits::default()};
        let mut tag_scratch=Vec::new();
        if visitor_mode&&tag_scratch.try_reserve_exact(MAX_ATTRIBUTES_PER_ELEMENT+1).is_err(){return Err(StreamStatus::Failed)}
        let mut open_names=Vec::new();if open_names.try_reserve_exact(MAX_DEPTH).is_err(){return Err(StreamStatus::Failed)}
